#include <iostream>
#include <print>
#include <string>

// Инвариант: low <= high.
class Range {
public:
    Range(int low, int high) {
        set_bounds(low, high);
    }

    int length() const {
        return high_ - low_;
    }

    void print() const {
        std::println("[{}, {}] длина {}", low_, high_, length());
    }

protected:
    void set_bounds(int low, int high) {
        low_ = low;
        high_ = high < low ? low : high;
    }

private:
    int low_ = 0;
    int high_ = 0;

protected:
    int low() const {
        return low_;
    }

    int high() const {
        return high_;
    }
};

class Window : public Range {
public:
    using Range::Range;

    void shrink_right(int d) {
        set_bounds(low(), high() - d);
    }

    void grow_left(int d) {
        set_bounds(low() - d, high());
    }
};

int main() {
    int a, b;
    std::cin >> a >> b;
    Window w(a, b);
    std::string command;
    int d;
    while (std::cin >> command >> d) {
        if (command == "shrink") {
            w.shrink_right(d);
        } else {
            w.grow_left(d);
        }
        w.print();
    }
    return 0;
}

