#include <print>

class Counter {
public:
    int value() const { return value_; }

protected:
    void bump(int d) { if (d > 0) value_ += d; }

private:
    int value_ = 0;
};

class Clicks : public Counter {
public:
    void click() { bump(1); }
    void hack() { bump(-100); }
};

int main() {
    Clicks c;
    c.click();
    c.click();
    c.hack();
    std::println("{}", c.value());
    return 0;
}
